ARTICLES = {
"ai-incident-database": {
 "kernel": "The AI Incident Database (AIID) is an editor-resolved database of AI harm events, run by the Responsible AI Collaborative and launched in 2020. Its unit is the incident, with the reports that document it attached, and every incident has a stable citation page at incidentdatabase.ai/cite/N.",
 "sections": [
  ("What it is", ["The AI Incident Database describes itself as \"dedicated to indexing the collective history of harms or near harms realized in the real world.\" It is a project of the Responsible AI Collaborative. Sean McGregor launched it and is its Executive Director; Partnership on AI was the database's founding sponsor. The founding paper (McGregor, arXiv:2011.08512, 17 November 2020) reported more than 1,000 incident reports at launch."]),
  ("How it works", ["Its unit is the incident: \"an alleged harm or near harm event to people, property, or the environment where an AI system is implicated.\" Reports (news articles, papers, posts) attach to incidents, and several reports may document one event. A distinct incident involving the same system, with substantially similar causes and harms, is recorded as a variant.",
                   "A candidate passes a five-question test: a specific event, an identifiable AI system, a causal AI role, harm or credible near harm, and adequate evidence. Anyone may submit. The incident editors resolve submissions. A duplicate is merged into the earlier record, and its citation page stays up and points there (Incident 637 now reads as a duplicate of 112). The whole database is offered as a weekly snapshot."]),
  ("What its selection leaves out", ["Its presumptive exclusions include \"Benchmark failures, model errors, or hallucinations that remain inside testing or private drafting and have no consequential use\" and \"General criticism of a product or technology class without identified harm.\" A measured study enters as a report when it documents an event. What an answer surface does with a source on an ordinary day, with no harm event, has no unit here: attribution erasure, citation fidelity and provenance stripping enter when they attach to a harm. Incident 693, Google's AI Overviews of May 2024, is the field's index case in the database, with seven reports."]),
  ("Place in the field", ["Its citation page per incident is the model this meta-aggregator follows. Its neighbours in the harm basin are the OECD AI Incidents and Hazards Monitor, which is automated and news-derived, and the AIAAIC Repository. The MIT AI Risk Repository aggregates risk frameworks over the same ground and keeps its own incident tracker."])]},
"papers-with-code": {
 "kernel": "Papers with Code (2018–2025) linked machine learning papers to their code and reported results, and its benchmark tables were the field's map of the state of the art. Founded by Robert Stojnic and Ross Taylor in 2018 and majority-owned by Facebook (later Meta) from December 2019, paperswithcode.com was sunset on 24 July 2025, and its data survives in CC BY-SA dumps. Its name now has a live instance, a revival at paperswithcode.co.",
 "sections": [
  ("What it was", ["Papers with Code linked machine learning papers to their code, the tasks and datasets they report on, and their results in benchmark tables. Robert Stojnic and Ross Taylor founded it in 2018 under Atlas ML. Facebook became majority owner of the operating company, Deeptide Ltd., on 13 December 2019, the day Stojnic announced it was joining Facebook AI. TechCrunch, reporting the acquisition in February 2020, gave the price as about $40 million, from its sources."]),
  ("How it ended", ["It was sunset on 24 July 2025. Julien Chaumond, co-founder and CTO of Hugging Face, announced the sunset the next day, with Trending Papers, launched by Hugging Face with Meta, as its replacement; the site had been failing with outages since early July (hyper.ai's report). No notice from Meta itself has been read. Trending Papers tracks popular papers with their code and carries no leaderboards. The data survives as five dumps (papers with abstracts, paper–code links, evaluation tables, methods, datasets) under CC BY-SA, linked from the paperswithcode-data repository on GitHub and hosted on Hugging Face."]),
  ("After", ["The name now lives at other addresses. A revival runs at paperswithcode.co, built by Niels Rogge of Hugging Face's open-source team, announced on r/MachineLearning and in a Community Article on Hugging Face in May 2026; its code, in Hugging Face's GitHub organization under Apache-2.0, \"recreates the original paperswithcode.com, which Meta retired in 2025.\" CodeSOTA carries the name in its own paths and presents itself as a successor. A current result attributed to paperswithcode.com comes from a table that stopped updating in July 2025; the revival is kept current by automated imports from Hugging Face, arXiv, GitHub and public leaderboards."]),
  ("Why it is here", ["A field aggregator held by a platform ended under that platform, and its record survives in dumps that others host. The meta-aggregator records dead aggregators with the same fields as live ones: the dead state, the date, and where the data went are part of the entity."])]},
}

ARTICLES.update({
"oecd-ai-incidents-monitor": {
 "kernel": "The OECD AI Incidents and Hazards Monitor (AIM) is an automated monitor of AI harm events in the news, developed by the OECD.AI expert group on AI incidents with the Patrick J. McGovern Foundation's support. It reads AI-tagged news events from Event Registry daily and, since November 2024, has large language models sort them into incidents and hazards and write their summaries; about 18,579 are listed.",
 "sections": [
  ("What it is", ["The monitor calls itself an \"Automated media discourse monitor of AI incidents and hazards (Beta).\" An AI incident is an event in which the development, use or malfunction of an AI system directly or indirectly leads to harm; an AI hazard is an event that \"could plausibly lead to an AI incident.\" The definitions follow the OECD's paper of May 2024."]),
  ("How it works", ["Event Registry clusters news articles about one happening into an event, and only events tagged with AI concepts reach the monitor. Since November 2024 a small model (GPT-4o mini) filters, a larger one (GPT-4o) reclassifies, and o3-mini writes the title, summary, harm type, severity, stakeholders and country from the top three articles. New items are matched to existing events by embedding similarity. The pipeline runs daily on events one to four days old."]),
  ("What its selection leaves out", ["An event enters when reputable outlets report it. A harm no outlet reports has no event to cluster. The record's own wording is machine-written from the articles, so the monitor is itself a machine reception of the news: its summaries are compositions, and the articles are their sources."]),
  ("Place in the field", ["It is the automated counterpart of the AI Incident Database, whose editors resolve each submission. A research study can enter it as an event: the Tow Center's 2025 study of AI search citation is filed as an incident."])]},
"aiaaic-repository": {
 "kernel": "The AIAAIC Repository records incidents and controversies driven by AI, algorithmic and automation systems. It began in June 2019 as a private, professional project, is licensed CC BY-SA 4.0, and has a newsletter, AIAAIC Alert, on Substack.",
 "sections": [
  ("What it is", ["The OECD's catalogue describes it as a repository that \"details incidents and controversies driven by and relating to artificial intelligence, algorithms, and automation,\" which \"collects, dissects, examines, and divulges a broad range of incidents and issues.\" It started in June 2019 \"as a private, professional project.\" Its newsletter, read in 92 countries by its own account, is written by Charlie Pownall."]),
  ("What its selection admits", ["Its unit is wider than harm. A controversy enters as a controversy, so public dispute about a system is recorded alongside events in which a system caused damage. Its name carries three kinds of system, algorithmic and automated as well as AI."]),
  ("Place in the field", ["It is the oldest of the three harm repositories in this census, beside the AI Incident Database and the OECD monitor. Its entry pages, intake process and current count were not read for this record."])]},
"mit-ai-risk-repository": {
 "kernel": "The MIT AI Risk Repository is a database of more than 1,700 AI risks extracted from 74 published risk frameworks (version 4, December 2025; the Initiative's home page gives 65+), run by the MIT AI Risk Initiative (MIT FutureTech) under CC BY 4.0. The Initiative's AI Incident Tracker, a workstream beside it, classifies AI Incident Database incidents against the same taxonomy.",
 "sections": [
  ("What it is", ["Its unit is the risk as a framework states it. Each source framework is summarized, and the source documents and key excerpts are published with it. The risks are sorted into a domain taxonomy with subdomains; the April 2025 update added a subdomain for multi-agent risks."]),
  ("What it gathers", ["It aggregates aggregators: its sources are frameworks, which are themselves syntheses. What enters is what a framework named. A risk no framework has written down has no row."]),
  ("Place in the field", ["Its incident layer is a second-order reading of the AI Incident Database, done by machine. The repository sits over the harm basin as a taxonomy for it."])]},
"mit-ai-incident-tracker": {
 "kernel": "The MIT AI Incident Tracker classifies AI Incident Database reports by risk domain, cause, harm, severity and EU AI Act risk level, using Arcola AI's language-model pipeline and the MIT Risk Repository taxonomy. Its own page calls the patterns indicative.",
 "sections": [
  ("What it is", ["It gives AIID's records a more consistent structure for policymakers, by its own account. The classification is machine-made: an LLM pipeline reads the raw AIID reports and assigns the MIT taxonomy and a severity rating based on CSET's AI Harm Taxonomy."]),
  ("What its record states about itself", ["The page gives its size twice, as \"more than 1,400\" in its description and 1,600 in its heading; the MIT AI Risk Navigator gives 1,497. It notes that reporting is voluntary, that no systematic validation study is complete, and that patterns \"should be taken as indicative.\""]),
  ("Place in the field", ["It is a derived layer: the editor-resolved incidents of AIID, reclassified by a model. The chain from event to news report to AIID record to machine classification is a chain of receptions, each recorded."])]},
"ai-hallucination-cases": {
 "kernel": "AI Hallucination Cases is Damien Charlotin's database of legal decisions in which a court or tribunal finds or implies reliance on hallucinated material: 2,231 decisions worldwide as of 28 October 2026, CC BY 4.0, with a CSV export.",
 "sections": [
  ("What it is", ["Its unit is the decision. A case enters when a court or tribunal addresses AI use in more than a passing reference and explicitly finds, or implies, reliance on hallucinated material. Mere allegations are excluded, with some judgment calls admitted. Each record carries the court, date, the party that used AI, the tool where named, the nature of the hallucination (fabricated, false quotes, misrepresented, outdated advice), and the outcome and sanction."]),
  ("What it shows", ["Of its cases, 1,288 involve pro se litigants and 880 lawyers. The period filter begins in the second quarter of 2023. The database grows by its editor's reading and by cases readers send."]),
  ("What its selection leaves out", ["It states its own boundary: it does not track \"the (necessarily wider) universe of all fake citations or use of AI in court filings.\" A fabricated citation enters when a court catches and rules on it."]),
  ("Place in the field", ["It is the census's most exact record of citation fidelity. Each entry is a machine composition that reached a court with sources it invented or misrepresented, and the court's decision is the reception that recorded it."])]},
"academ-ai": {
 "kernel": "Academ-AI is Alex Glynn's database of published scholarship with suspected undeclared use of AI, identified by chatbot phrasing and quoted with the phrases highlighted: 772 examples in August 2025 (633 journal articles, 111 conference papers, 28 books and chapters).",
 "sections": [
  ("What it is", ["Alex Glynn, a research literacy instructor at the University of Louisville's Kornhauser Health Sciences Library, built it. An entry is a published work whose text carries phrasing that strongly suggests a chatbot wrote it, without any disclosure. Each passage is quoted with the tell-tale phrases highlighted. Journal articles, conference papers, books and dissertations are admitted; preprints, blog posts and other media are out of scope (its About page, 2026-10-29)."]),
  ("What it records beyond the case", ["An errata page sorts what happened after: corrections with formal explanations, and \"stealth revisions\" made with none. A publishers page counts cases by publisher; in August 2025 IEEE led with 90 and Elsevier followed with 34. Glynn's dataset paper (arXiv:2411.15218) analysed the first 768 examples and found undeclared use more often in journals with higher citation metrics and higher article charges."]),
  ("What its selection leaves out", ["The unit is a detectable trace. Glynn's paper says the cases found are likely a small fraction, since much undeclared use leaves no phrase behind."]),
  ("Place in the field", ["With the Problematic Paper Screener it records machine composition entering the scholarly record unattributed: the machine is the uncredited author, and the publisher is where the reception happens."])]},
"problematic-paper-screener": {
 "kernel": "The Problematic Paper Screener, run by Guillaume Cabanac with Cyril Labbé and Alexander Magazinov since 27 February 2021, scans the scientific literature weekly for papers generated or disguised by tools (tortured phrases, SCIgen, Mathgen) and for references to retracted work.",
 "sections": [
  ("What it is", ["It is a set of detectors run over the literature: tortured phrases (the output of paraphrasing tools, such as \"Joined Together States\" for \"United States\"), SCIgen and Mathgen papers, references that are annulled or under concern, and others. Its sources are Crossref with the Retraction Watch Database, Dimensions, PubMed and PubPeer. It scans 130 million publications a week."]),
  ("What it has found", ["By January 2025: nearly 19,000 papers with five or more tortured phrases, more than 280 SCIgen papers, more than 70 with ChatGPT fingerprints, and more than 764,000 articles citing retracted work. It has contributed to more than 1,000 retractions."]),
  ("What its selection leaves out", ["A detector finds what leaves a fingerprint. Text machine-written cleanly, or cited sources that exist but say something else, pass beneath it."]),
  ("Place in the field", ["It is the scholarly record's automated immune response, and the neighbour of Academ-AI, which reads by phrase where the screener reads by detector."])]},
"newsguard-ai-tracking-center": {
 "kernel": "NewsGuard's AI Tracking Center catalogues AI content farm websites, unreliable news sites run with little or no human oversight: 3,749 in 16 languages as of 23 June 2026. It also hosts NewsGuard's recurring AI False Claim Monitor.",
 "sections": [
  ("What it is", ["A domain enters when it meets all four criteria: a substantial share of its content is AI-produced; the content is published without meaningful human oversight (chatbot error text is one sign); its layout or name could lead a reader to think human journalists wrote it; and it carries no clear disclosure."]),
  ("What its selection leaves out", ["Disclosure takes a site out. A site that says its content is machine-made is outside the catalogue whatever it publishes."]),
  ("Place in the field", ["It records the supply side of machine-mediated reception: the sites that answer surfaces may retrieve and cite. Its series, the False Claim Monitor, records the composition side."])]},
"newsguard-ai-false-claim-monitor": {
 "kernel": "NewsGuard's AI False Claim Monitor is a recurring audit of leading chatbots on false claims in the news: its editions were titled monthly until mid-2025 and quarterly since, while its method page still says monthly. The May 2026 edition, published 8 June 2026, tested 11 named chatbots on 10 provably false claims.",
 "sections": [
  ("What it is", ["Each edition puts the same false claims to the leading chatbots and records whether they repeat them. The May 2026 edition named ChatGPT-5.2, You.com's Smart Assistant, Grok, Pi, Claude, Le Chat, Copilot, Meta AI, Gemini, Perplexity and DeepSeek. The January 2026 edition reported, by the method page, that the tools repeated false claims more than 28% of the time."]),
  ("How its record is held", ["Each edition's full results sit behind a download form, so the public page carries the frame and the headline."]),
  ("Place in the field", ["It is a recurring audit that names the vendors it tests. It measures whether a false claim is passed on, which sits beside, and apart from, whether a true source is credited."])]},
"presenc-geo-papers": {
 "kernel": "Presenc AI's GEO academic papers page, published 23 April 2026 by its CTO, gathers 34 papers and reports on generative engine optimization in five themes, each with a vendor note on what it means for practitioners.",
 "sections": [
  ("What it is", ["Presenc AI, a commercial AI-visibility vendor, groups 34 items (conference papers, preprints, a thesis, a journal article, and blog-style and whitepaper items) under five themes: content-level optimization, structural and metadata signals, adversarial security, measurement and governance, and comparative or sector studies. Each carries title, authors, venue, link and key finding, and a Presenc note."]),
  ("How it reads the literature", ["The page states that \"the Presenc AI audit framework is directly anchored in this literature,\" ties several findings to its features, and closes on a waitlist. Eight entries are authored by \"AIVO Standard,\" whose relation to Presenc the page does not give."]),
  ("Place in the field", ["It is the fullest of the optimization-side lists, and the literature it gathers is read toward its product. Its selection is the GEO literature as a vendor needs it."])]},
"awesome-geo-davidhuji": {
 "kernel": "Awesome-GEO is a GitHub awesome list of research on generative engine optimization maintained by DavidHuji: about 27 papers, code, datasets and tools in sections by year (2024–2026) and open-source resources, with 123 stars.",
 "sections": [
  ("What it is", ["It is a single README in the awesome-list form: entries linked to paper, code, dataset or tool, grouped by year. Fourteen pull requests were listed when it was read."]),
  ("Place in the field", ["It is the research-side list of the optimization basin; it adds no reading of its own to each paper, and credits two of its tools to the companies that built them. Its name collides with the many geospatial awesome lists, and the negative tag marks the difference."])]},
"aeovision-geo-papers": {
 "kernel": "AEO Vision's list of the top arXiv papers for generative engine optimization, dated 15 July 2026 and bylined to its content team, summarizes 12 papers, each with a takeaway for teams.",
 "sections": [
  ("What it is", ["A vendor article: 12 papers with authors, arXiv links and summaries, a quick-reference table of why each matters, and a takeaway for teams under each. It closes on its product: \"That is the measurement loop AEO Vision is built for.\""]),
  ("Place in the field", ["With Presenc's page it shows the optimization basin's typical aggregator: the research gathered as the warrant for a measurement product."])]},
"codesota": {
 "kernel": "CodeSOTA, by Kacper Wikiel for Fabryka AI in Warsaw, is a routing layer for AI tasks on its homepage (\"One Routing Layer for AI Tasks\") and a successor to Papers with Code on its /papers-with-code/ pages (\"Codesota is the v2 replacement for what PWC did\"). It offers leaderboards with verification dates, an open JSON registry and /api/sota.",
 "sections": [
  ("What it is", ["It rebuilds benchmark tracking \"independently\": leaderboards whose scores carry verification dates and code links, paper discovery, a dataset registry, task pages, and an API. It hosts historical Papers with Code data at /browse/pwc and links the frozen paperswithcode-data archive as a source."]),
  ("How it holds the name", ["Its homepage presents the routing product and names Papers with Code only in a footer link. Its pages under /papers-with-code/, a shutdown record and a trending page among them, present the succession. The figures it gives for Papers with Code (9,327 benchmarks, 79,817 papers, 5,628 datasets) are the dead aggregator's; its own catalogue counts are not given."]),
  ("Place in the field", ["It is the clearest case in the census of a successor claim made in the name's own address space, and of an entity with three faces at three addresses: a routing layer on its homepage, a successor on its /papers-with-code/ pages, and on its about page \"an independent registry of machine-learning benchmarks\" that refuses the aggregator class. Google's Overview composes the homepage's routing layer and leaves the succession unsaid. The Papers with Code record keeps the two apart, and the revival at paperswithcode.co is a third claimant to the name."])]},
"data-provenance-explorer": {
 "kernel": "The Data Provenance Explorer, from the Data Provenance Initiative (Longpre, Mahari and others), traces the sources and licences of AI training datasets: nearly 4,000 text, speech and video datasets by its own count. Its founding audit covered more than 1,800 text datasets and found licence omission above 70% and error rates above 50%.",
 "sections": [
  ("What it is", ["The Initiative calls its work \"public measurement infrastructure for AI data, model ecosystems, and real-world AI use.\" The Explorer lets practitioners trace and filter the provenance of popular open fine-tuning collections, back to their sources, creators and licences."]),
  ("What its audits found", ["The founding audit (arXiv:2310.16787) found \"license omission of 70%+ and error rates of 50%+\" on dataset hosting sites. Consent in Crisis (arXiv:2407.14933, NeurIPS 2024) read 14,000 web domains and found that \"a full 45% of C4 is now restricted\" by terms of service."]),
  ("Place in the field", ["It records provenance at the training layer, where the census's reception aggregators record it at the composition layer. The two ends of one chain: what a model was given, and what it credits when it answers."])]},
"cms-ai-copyright-tracker": {
 "kernel": "The CMS AI and Copyright Case Tracker, compiled by the law firm CMS, summarizes 23 court cases on AI and copyright from 10 jurisdictions, led by Germany; the newest entry is dated 31 July 2026, and no US cases are listed.",
 "sections": [
  ("What it is", ["Each case has a summary page: case name, jurisdiction, date, the litigation, each party's arguments and the judgment. The jurisdictions are Germany, the UK, the Netherlands, Hungary, China, France, Italy, India, Austria and the Czech Republic. Uncovered cases may be sent to a submission address."]),
  ("Place in the field", ["It records the legal reception of the provenance question: what courts decide about training on, and outputting, protected work. With no US cases listed, it sits beside the US litigation trackers, which were not read for this census."])]},
"search-arena": {
 "kernel": "Search Arena ranks search-enabled language models by head-to-head human votes: 42 models on its search board in Arena's published data of 13 October 2026. Its dataset paper (ICLR 2026) found that users prefer answers with more citations even when the citations do not support the claims.",
 "sections": [
  ("What it is", ["A leaderboard on arena.ai: users compare two search-augmented answers and vote, and models are rated with confidence intervals from the battles. Its paper (Miroyan et al., arXiv:2506.05334) released over 24,000 paired multi-turn interactions with about 12,000 votes."]),
  ("What it found about citation", ["User preference rises with the number of citations even when the cited content does not support the claim it is attached to, a gap between perceived and actual credibility. Preference also varies by source: community platforms are generally preferred, and static encyclopedic sources are not always judged appropriate."]),
  ("Place in the field", ["Its leaderboard rewards what users prefer, and its paper shows that preference rewarding citation count over citation support. The released interactions are original outputs, preserved."])]},
"capture-registry": {
 "kernel": "The AI Overview Capture Registry, run by the Crimson Hexagonal Archive, records dated compositions by machine answer surfaces at named addresses, each with its verbatim transcript and the sources it engaged: 792 captures and 981 observations at registry version 12.345.",
 "sections": [
  ("What it is", ["Its unit is the capture: one composition by an answer surface (Google's AI Overview and AI Mode, ChatGPT, and others) at one address, the exact query, on one date. The rule of admission is its operator's: a capture enters the registry by means of source engagement in composition. The transcript is the capture, kept verbatim with its citations extracted as data. A later run at a seated address is an observation of the same address."]),
  ("What its selection leaves out", ["Its addresses are chosen by its operator, and most concern the archive's own entities, so it is a record of how those entities are received. A query with no source engagement at a new address does not enter."]),
  ("Place in the field", ["It is the census's one aggregator whose unit is the composition itself, recorded before any harm is established or any study is written. It is also the operator of this meta-aggregator, and its record carries the same fields as every other."])]},
})

ARTICLES["papers-with-code-revival"] = {
 "kernel": "Papers with Code at paperswithcode.co is a revival of the dead aggregator, built by Niels Rogge of Hugging Face's open-source team and announced in May 2026; its code, in Hugging Face's GitHub organization under Apache-2.0, \"recreates the original paperswithcode.com, which Meta retired in 2025.\"",
 "sections": [
  ("What it is", ["It tracks trending machine learning research with code, datasets and leaderboards, kept current by automated imports from Hugging Face, arXiv, GitHub and public leaderboards, by its README. The live site describes itself as a place to \"discover trending machine-learning papers, methods, benchmarks, datasets, and open-source implementations.\""]),
  ("How it entered the census", ["The census of 28 October recorded the revival as an undated individual effort under the dead aggregator's page. The capture of 29 October at \"is papers with code still active\" answered yes and named the revival at its new domain; its repository, read the same day, confirmed it. The record is the census corrected by the composition layer."]),
  ("What is held apart", ["Its standing is described two ways: Google's Overview says Hugging Face \"officially stepped in\"; AI Weekly called it an individual effort. The code sits in Hugging Face's organization. The original's frozen dumps, CodeSOTA's succession claim and this revival are three entities around one name, and the census keeps each."])]}
